  function fresh(c){return{step:1,verdict:c.verdict,intent:c.intent,scenario:'normal',supply:false,analyzed:false,selected:[],feedback:c.feedback,includeFeedback:true,includeJobs:false,approved:null,sent:null,response:null,received:null,events:[]};}
  function jobs(c,s){return c.jobs.map(j=>({...j,eligible:j.eligible&&s.intent==='yes'&&s.verdict==='不推进'&&s.scenario==='normal',blocked:s.scenario==='closed'?'岗位已关闭':s.scenario==='city'?'城市不符合候选人意向':s.intent!=='yes'?'转推意愿未确认':s.verdict!=='不推进'?'原岗位结果不满足触发条件':!j.eligible?'关键证据待确认':null})).sort((a,b)=>(Number(b.eligible)-Number(a.eligible))||(s.supply?(Number(b.need)-Number(a.need)):0));}
  function chosen(c,s){return jobs(c,s).filter(j=>j.eligible&&s.selected.includes(j.id));}
