  function validate(c,s){if(!s.analyzed)return'请先完成面评确认与岗位复核';if(s.verdict!=='不推进')return'原岗位尚未确认不推进，请先处理原流程';if(s.includeFeedback&&!s.feedback.trim())return'已勾选反馈，但反馈内容为空';if(s.includeJobs&&!chosen(c,s).length)return'岗位邀请需要至少一个有效且已选择的岗位';return'';}
