  function respond(s,value){if(!s.sent||!s.sent.jobs.length)return'没有已发出的岗位邀请';if(s.response)return'该邀请已处理';if(value!=='decline'&&!s.sent.jobs.some(j=>j.id===value))return'请选择已获邀的岗位';s.response=value;return'';}
